// White-tail side views for the aircraft tiles: original drawings generated by scripts/sideviews (pnpm --filter
// @arg/app sideviews) from published dimensions, one SVG per type in public/aircraft/. drawings.json lists the types
// that have one; a type without a drawing falls back to the simple SideView silhouette.
import drawings from "./drawings.json";

export const AIRCRAFT_DRAWINGS: ReadonlySet<string> = new Set(drawings);

/** URL of a type's side-view drawing, or null when it has none (the tile then draws the generic side view). */
export function aircraftImageUrl(typeId: string, base: string = import.meta.env.BASE_URL): string | null {
  return AIRCRAFT_DRAWINGS.has(typeId) ? `${base}aircraft/${typeId}.svg` : null;
}
